{
  "decline_reason": "",
  "claims": [
    {
      "text": "Under the Manual’s search-indexing practice, the constituent LTR indicates a letter or letters.",
      "quotes": [
        {
          "ref": "TMM/Part5/x-word-constituents/letters",
          "quote": "To indicate a letter or letters the constituent LTR is used."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For a single letter in a trade mark, # is added to the constituents as well as LTR.",
      "quotes": [
        {
          "ref": "TMM/Part5/x-word-constituents/letters",
          "quote": "Where there is a single letter in the trade mark, # is added to the constituents as well as LTR."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For groups of letters, an additional constituent prefixed with an equals sign is used to distinguish the letter group from the same letters used as a word.",
      "quotes": [
        {
          "ref": "TMM/Part5/x-word-constituents/letters",
          "quote": "A constituent with an equals sign prefix is added to the constituent for groups of letters. It is useful in enabling searchers to distinguish between a group of letters and the same letters used as a word."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "A group clearly recognised as an acronym is indexed as letters even if it spells a word.",
      "quotes": [
        {
          "ref": "TMM/Part5/x-word-constituents/letters",
          "quote": "In addition, when a group of letters is clearly an acronym, although it spells a word, it is indexed as letters."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Letters attached to the beginning or end of a word are indexed separately if they remain recognisable as letters; for example, TDELTA receives the additional constituents T and LTR.",
      "quotes": [
        {
          "ref": "TMM/Part5/x-word-constituents/letters-which-occur-within-a-word-or-attached-to-words",
          "quote": "Letters which are joined to the beginning or ending of a word (so long as they are still recognised as letters) are indexed as separate constituents. For example the mark TDELTA would be indexed with the additional constituents T and LTR."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "A letter appearing as a separate entity within a word is also indexed, but an insignificant central letter is not, subject to discretion for specially represented letters.",
      "quotes": [
        {
          "ref": "TMM/Part5/x-word-constituents/letters-which-occur-within-a-word-or-attached-to-words",
          "quote": "Letters which feature as a separate entity in the middle of words are also indexed (eg. RED-I-BEAM indexing would include I and LTR). However if the central letter is an insignificant feature such as the letter N in RUFF-N-READY or the letter A in DIAL-A-PIZZA, the letter is not indexed."
        },
        {
          "ref": "TMM/Part5/x-word-constituents/letters-which-occur-within-a-word-or-attached-to-words",
          "quote": "However, discretion needs to be used in case of specially represented letters."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The usual test for separately indexing a prefix as letters is whether it would be pronounced as a letter or letters given the nature of the goods or services.",
      "quotes": [
        {
          "ref": "TMM/Part5/x-word-constituents/letters-which-occur-within-a-word-or-attached-to-words",
          "quote": "The test for rendering a character or character string as letters is usually based on pronunciation. If you would expect the prefix to be pronounced as a letter or letters because of the nature of the goods or services, then the prefix will be indexed separately."
        }
      ],
      "authority": "manual"
    }
  ],
  "declined": false,
  "concepts_used": [
    "GC-0072"
  ]
}
